#!/usr/bin/env python3
"""Generate C++ catalog header from catalogs/algorithms.json (single source of truth)."""

from __future__ import annotations

import argparse
import json
from pathlib import Path


def esc(s: str) -> str:
    return s.replace("\\", "\\\\").replace('"', '\\"')


def generate(catalog: dict) -> str:
    lines = [
        "// AUTO-GENERATED by scripts/generate_catalog_artifacts.py — DO NOT EDIT.",
        "// Source of truth: catalogs/algorithms.json",
        "#pragma once",
        "",
        "#include <cstddef>",
        "#include <string>",
        "",
        "namespace proofrun {",
        "namespace catalog {",
        "",
        "struct AlgorithmInfo {",
        "  const char* id;",
        "  const char* name;",
        "  const char* family;",
        "  const char* best;",
        "  const char* avg;",
        "  const char* worst;",
        "  const char* memory;",
        "  const char* explanation;",
        "  bool visualizable;",
        "  bool benchmarkable;",
        "  bool traceable;",
        "  const char* status;",
        "};",
        "",
        "inline constexpr AlgorithmInfo kAlgorithms[] = {",
    ]
    for a in catalog["algorithms"]:
        c = a["complexity"]
        lines.append(
            "  {"
            f'"{esc(a["id"])}", '
            f'"{esc(a["name"])}", '
            f'"{esc(a["family"])}", '
            f'"{esc(c["best"])}", '
            f'"{esc(c["avg"])}", '
            f'"{esc(c["worst"])}", '
            f'"{esc(c["memory"])}", '
            f'"{esc(a["explanation"])}", '
            f'{"true" if a.get("visualizable") else "false"}, '
            f'{"true" if a.get("benchmarkable") else "false"}, '
            f'{"true" if a.get("traceable") else "false"}, '
            f'"{esc(a.get("status", "unknown"))}"'
            "},"
        )
    lines += [
        "};",
        "",
        "inline constexpr std::size_t kAlgorithmCount =",
        "    sizeof(kAlgorithms) / sizeof(kAlgorithms[0]);",
        "",
        "inline const AlgorithmInfo* find(const std::string& id) {",
        "  for (std::size_t i = 0; i < kAlgorithmCount; ++i) {",
        "    if (id == kAlgorithms[i].id) return &kAlgorithms[i];",
        "  }",
        "  return nullptr;",
        "}",
        "",
        "}  // namespace catalog",
        "}  // namespace proofrun",
        "",
    ]
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", type=Path, default=None)
    parser.add_argument("--check", action="store_true", help="Fail if generated output differs")
    args = parser.parse_args()
    root = args.root or Path(__file__).resolve().parents[1]
    src = root / "catalogs" / "algorithms.json"
    out = root / "cpp" / "include" / "proofrun" / "catalog" / "generated_algorithms.hpp"
    catalog = json.loads(src.read_text(encoding="utf-8"))
    text = generate(catalog)
    if args.check:
        if not out.exists():
            raise SystemExit(f"missing generated header: {out}")
        existing = out.read_text(encoding="utf-8")
        if existing != text:
            raise SystemExit("catalog drift: generated_algorithms.hpp is out of date; run generate_catalog_artifacts.py")
        print("catalog header up to date")
        return 0
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(text, encoding="utf-8")
    print(f"wrote {out}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
